import { concatBytes, normalizeBytes, sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(keyInput, messageInput) {
  let key = normalizeBytes(keyInput);

  if (key.length > BLOCK_SIZE) {
    key = sha256(key);
  }

  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(key);

  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerPad[index] = paddedKey[index] ^ 0x36;
    outerPad[index] = paddedKey[index] ^ 0x5c;
  }

  const innerHash = sha256(concatBytes([innerPad, normalizeBytes(messageInput)]));
  return sha256(concatBytes([outerPad, innerHash]));
}

