export function encodeJwt(payload, secret) {
  const payloadSegment = stringToBase64Url(JSON.stringify(payload));
  const signingInput = `${HEADER_SEGMENT}.${payloadSegment}`;
  const signature = hmacSha256(secret, signingInput);

  return `${signingInput}.${bytesToBase64Url(signature)}`;
}

