function escapeWithQuote(value, quote) {
  let result = '';

  for (const character of value) {
    switch (character) {
      case '\\':
        result += '\\\\';
        break;
      case '\n':
        result += '\\n';
        break;
      case '\r':
        result += '\\r';
        break;
      case '\t':
        result += '\\t';
        break;
      case '\b':
        result += '\\x08';
        break;
      case '\f':
        result += '\\x0c';
        break;
      case '\v':
        result += '\\x0b';
        break;
      default: {
        const codePoint = character.codePointAt(0);

        if (character === quote) {
          result += `\\${quote}`;
        } else if (
          codePoint < 0x20 ||
          (codePoint >= 0x7f && codePoint <= 0x9f)
        ) {
          result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
        } else {
          result += character;
        }
      }
    }
  }

  return result;
}

export function formatPythonString(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  return `${quote}${escapeWithQuote(value, quote)}${quote}`;
}

export function formatPythonValue(value) {
  if (typeof value === 'string') {
    return formatPythonString(value);
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map(formatPythonValue).join(', ')}]`;
  }

  if (typeof value === 'object') {
    const entries = Object.entries(value).map(
      ([key, nestedValue]) =>
        `${formatPythonString(key)}: ${formatPythonValue(nestedValue)}`,
    );

    return `{${entries.join(', ')}}`;
  }

  return formatPythonString(String(value));
}

