function formatUsage(programName) {
  return `usage: ${programName} [-h] --payload PAYLOAD --secret SECRET`;
}

function formatHelp(programName) {
  return `${formatUsage(programName)}

options:
  -h, --help         show this help message and exit
  --payload PAYLOAD
  --secret SECRET
`;
}

function formatError(programName, message) {
  return `${formatUsage(programName)}
${programName}: error: ${message}
`;
}

function isNegativeNumberToken(value) {
  return /^-(?:\d+|\d*\.\d+)$/.test(value);
}

function isOptionLikeToken(value) {
  return value !== undefined && value.startsWith('-') && !isNegativeNumberToken(value);
}

function findLongOptionMatches(optionToken) {
  const longOptions = ['--help', '--payload', '--secret'];
  return longOptions.filter((candidate) => candidate.startsWith(optionToken));
}

function resolveLongOption(token) {
  if (token === '--') {
    return { type: 'end-of-options' };
  }

  const equalsIndex = token.indexOf('=');
  const optionToken = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
  const explicitValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
  const matches = findLongOptionMatches(optionToken);

  if (matches.length === 0) {
    return { type: 'unknown' };
  }

  if (matches.length > 1) {
    return {
      type: 'ambiguous',
      matches,
    };
  }

  return {
    type: 'resolved',
    option: matches[0],
    explicitValue,
  };
}

export class ArgparseExit extends Error {
  constructor(code, stream, text) {
    super(text);
    this.name = 'ArgparseExit';
    this.code = code;
    this.stream = stream;
    this.text = text;
