export function parseArgs(argv, programName = 'test8.mjs') {
  const result = {
    payload: undefined,
    secret: undefined,
  };
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h') {
      throw new ArgparseExit(0, 'stdout', formatHelp(programName));
    }

    if (token.startsWith('-h=')) {
      throw new ArgparseExit(
        2,
        'stderr',
        formatError(
          programName,
          `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
        ),
      );
    }

    if (token.startsWith('-h') && token !== '--') {
      throw new ArgparseExit(0, 'stdout', formatHelp(programName));
    }

    if (token.startsWith('--')) {
      const resolution = resolveLongOption(token);

      if (resolution.type === 'end-of-options') {
        extras.push(...argv.slice(index + 1));
        break;
      }

      if (resolution.type === 'ambiguous') {
        throw new ArgparseExit(
          2,
          'stderr',
          formatError(
            programName,
            `ambiguous option: ${token} could match ${resolution.matches.join(', ')}`,
          ),
        );
      }

      if (resolution.type === 'unknown') {
        extras.push(token);
        continue;
      }

      if (resolution.option === '--help') {
        if (resolution.explicitValue !== null) {
          throw new ArgparseExit(
            2,
            'stderr',
            formatError(
              programName,
              `argument -h/--help: ignored explicit argument '${resolution.explicitValue}'`,
            ),
          );
        }

        throw new ArgparseExit(0, 'stdout', formatHelp(programName));
      }

      const key = resolution.option.slice(2);

      if (resolution.explicitValue !== null) {
        result[key] = resolution.explicitValue;
        continue;
      }

      const nextToken = argv[index + 1];

      if (nextToken === undefined || isOptionLikeToken(nextToken)) {
        throw new ArgparseExit(
          2,
          'stderr',
          formatError(programName, `argument ${resolution.option}: expected one argument`),
        );
      }

      result[key] = nextToken;
      index += 1;
      continue;
    }

    extras.push(token);
  }

  const missing = [];

  if (result.payload === undefined) {
    missing.push('--payload');
  }

  if (result.secret === undefined) {
    missing.push('--secret');
  }

  if (missing.length > 0) {
    throw new ArgparseExit(
      2,
      'stderr',
      formatError(
        programName,
        `the following arguments are required: ${missing.join(', ')}`,
      ),
    );
  }

  if (extras.length > 0) {
    throw new ArgparseExit(
      2,
      'stderr',
      formatError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    );
  }

  return result;
}

