const encoder = new TextEncoder();
const decoder = new TextDecoder();

export function toUtf8Bytes(value) {
  return encoder.encode(String(value));
}

export function fromUtf8Bytes(bytes) {
  return decoder.decode(bytes);
}

export function bytesToBase64Url(bytes) {
  return Buffer.from(bytes)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

export function stringToBase64Url(value) {
  return bytesToBase64Url(toUtf8Bytes(value));
}

export function base64UrlToBytes(value) {
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
  const paddingLength = (4 - (normalized.length % 4)) % 4;
  const padded = normalized + '='.repeat(paddingLength);
  return Uint8Array.from(Buffer.from(padded, 'base64'));
}

export function base64UrlToString(value) {
  return fromUtf8Bytes(base64UrlToBytes(value));
}
